const obs = phi.observe();
const links = phi.query("a", { fields: ["href"], limit: 200 });
const aero = links.items.filter(i => i.href && /aero|api|pricing/i.test(i.href));
return { title: obs.title, url: obs.url, totalLinks: links.total, aero: aero.slice(0,40) };

const r = phi.goto("https://www.flightaware.com/commercial/aeroapi/");
const t = phi.text();
return { r, text: t.slice(0, 3000) };

const t = phi.recall("$step4");
const txt = t.text || "";
const anchors = phi.query("a[href*='pricing'], a[href*='tier']", { fields: ["href"], limit: 50 });
return { len: txt.length, anchors: anchors.items, tail: txt.slice(2000, 7000) };

phi.click("a[href='#pricing-cards']");
phi.sleep(800);
const cards = phi.query("#pricing-cards", { limit: 3 });
const secs = phi.query("section", { fields: ["id"], limit: 40 });
return { cards: cards.items.map(i => i.text ? i.text.slice(0,2500) : i), secs: secs.items };

const out = {};
for (const id of ["pricing-cards","compare-tiers","pricing-table","volume-discounting-table"]) {
  const el = document.getElementById(id);
  out[id] = el ? el.innerText.replace(/\n{2,}/g,"\n").trim() : null;
}
phi.keep("aeroapi_sections", out);
return Object.fromEntries(Object.entries(out).map(([k,v])=>[k, v ? v.length : null]));

const out = phi.js(() => {
  const ids = ["pricing-cards","compare-tiers","pricing-table","volume-discounting-table"];
  const res = {};
  for (const id of ids) {
    const el = document.getElementById(id);
    res[id] = el ? el.innerText.replace(/\n{2,}/g, "\n").trim() : null;
  }
  return res;
});
phi.keep("aeroapi_zh", Object.fromEntries(Object.entries(out).map(([k,v]) => [k, (v||"").slice(0,4000)])));
return Object.fromEntries(Object.entries(out).map(([k,v]) => [k, v ? v.length : null]))

const d = phi.recall("aeroapi_zh");
const pt = d["pricing-table"] || "";
const vd = d["volume-discounting-table"] || "";
// widen: re-read pricing table fully and in narrow scopes if truncated
const full = phi.js(() => {
  const g = (id) => { const el = document.getElementById(id); return el ? el.innerText.replace(/\n{2,}/g,"\n").trim() : null; };
  return { pt: g("pricing-table"), vd: g("volume-discounting-table") };
});
phi.keep("aeroapi_fees", { pt: (full.pt||"").slice(0,3000), vd: (full.vd||"").slice(0,1500), ptLen: (full.pt||"").length, vdLen: (full.vd||"").length });
return { ptLen: (full.pt||"").length, vdLen: (full.vd||"").length, pt: full.pt, vd: full.vd };

const out = {};
const tabs = [
  { ref: 3, name: "Foresight" },
  { ref: 4, name: "Airports" },
  { ref: 5, name: "Operators" },
  { ref: 6, name: "Alerts" },
  { ref: 7, name: "History" },
  { ref: 8, name: "Miscellaneous" },
  { ref: 9, name: "Account" },
];
for (const t of tabs) {
  const r = phi.click(t.ref);
  phi.sleep(400);
  const txt = phi.js(() => {
    const el = document.getElementById("pricing-table");
    return el ? el.innerText.replace(/\n{2,}/g, "\n").trim() : null;
  });
  out[t.name] = (txt || "").replace(/^Query fees breakdown[\s\S]*?Compare tiers\n/, "");
}
phi.keep("aeroapi_fees_tabs", out);
return Object.fromEntries(Object.entries(out).map(([k, v]) => [k, (v || "").length]));

const d = phi.recall("aeroapi_zh") || {};
const cards = d["pricing-cards"] || "";
// also re-read the plan cards live, in narrow scopes
const live = phi.js(() => {
  const out = {};
  const grab = (sel) => Array.from(document.querySelectorAll(sel)).map(e => e.innerText.replace(/\n{2,}/g,"\n").trim()).filter(Boolean);
  out.h2 = Array.from(document.querySelectorAll("h2, h3")).map(e => e.innerText.trim()).filter(t => t.length < 80).slice(0,40);
  out.cards = grab("[id*=card], .pricing-card, [class*=tier], [class*=plan]").slice(0,12);
  return out;
});
return { keptCardsLen: cards.length, keptCards: cards.slice(0, 2500), live };
